25	// longRun returns a full netdiag.Model on the Path tab, sized width x height,
26	// with the 30-hop trace of longHost in the given state: running, done, canceled.
27	func longRun(t *testing.T, width, height int, state string) *Model {
28		t.Helper()
29		m := onPathTab(t)
30		m = feed(t, m, tea.WindowSizeMsg{Width: width, Height: height})
31		m = feed(t, m, testutil.Type(longHost)...)
32		m = feed(t, m, testutil.Key("enter"))
33		gen := m.pathModel.gen
34	
35		route := netcheck.RouteHop{Interface: longIface, Source: net.ParseIP("192.168.1.21"), Gateway: net.ParseIP("192.168.1.1")}
36		m = feed(t, m, pathResolvedMsg{gen: gen, addr: netip.MustParseAddr("198.51.100.30"), route: route})
37	
38		var hops []nettrace.Hop
39		for ttl := 1; ttl <= manyHops; ttl++ {
40			h := nettrace.Hop{TTL: ttl, Kind: nettrace.HopRouter, Addr: netip.MustParseAddr("2001:db8:85a3:0:0:8a2e:370:7334")}
41			switch {
42			case ttl == manyHops:
43				h = nettrace.Hop{TTL: ttl, Kind: nettrace.HopTarget, Addr: netip.MustParseAddr("198.51.100.30")}
44			case ttl%4 == 0:
45				h = nettrace.Hop{TTL: ttl, Kind: nettrace.HopSilent}
46			case ttl%2 == 0:
47				h.Addr = netip.MustParseAddr("10.0.0." + string(rune('0'+ttl%10)))
48			}
49			hops = append(hops, h)
50			m = feed(t, m, pathHopMsg{gen: gen, hop: h})
51		}
52		switch state {
53		case "done":
54			m = feed(t, m, pathDoneMsg{gen: gen, result: nettrace.Result{Outcome: nettrace.OutcomeReached, Hops: hops}})
55		case "canceled":
56			m = feed(t, m, testutil.Key("esc"))
57		}
58		return m
59	}
