61	// Criterion 3: no line overflows and no escape sequence is cut. A cut escape
62	// would eat visible cells, so the exact width is what detects it.
63	func TestPathColumnFitsTheTerminalWidth(t *testing.T) {
64		for _, width := range []int{80, 60} {
65			for _, state := range []string{"running", "done", "canceled"} {
66				t.Run(strings.Join([]string{state, string(rune('0' + width/10))}, "-"), func(t *testing.T) {
67					m := longRun(t, width, 24, state)
68					body := m.Render()
69					for i, line := range strings.Split(body, "\n") {
70						if w := ansi.StringWidth(line); w != width-2 {
71							t.Errorf("body line %d is %d cells wide, want %d: %q", i, w, width-2, ansi.Strip(line))
72						}
73					}
74					if got := m.pathModel.table.RenderedWidth(); got != width-2 {
75						t.Errorf("RenderedWidth = %d, want %d (Rule 116)", got, width-2)
76					}
77					plain := ansi.Strip(body)
78					if strings.ContainsRune(plain, '\x1b') {
79						t.Errorf("an escape sequence survives the strip (cut sequence):\n%q", plain)
80					}
81					if !strings.Contains(plain, "this machine") {
82						t.Errorf("body lacks %q:\n%s", "this machine", plain)
83					}
84					if !strings.Contains(plain, "…") {
85						t.Errorf("the %d-cell interface name is not truncated with a mark:\n%s", len(longIface), plain)
86					}
87					for i, line := range strings.Split(m.RenderFooter(width), "\n") {
88						if w := ansi.StringWidth(line); w > width {
89							t.Errorf("footer line %d is %d cells wide, want <= %d", i, w, width)
90						}
91					}
92				})
93			}
94		}
95	}
