97	// Criterion 4: more rows than lines, the navigation keys scroll the column in
98	// every state (the table takes them whatever the state).
99	func TestPathColumnScrollsWithTheNavigationKeys(t *testing.T) {
100		const first, last = "this machine", "198.51.100.30"
101		for _, state := range []string{"running", "done", "canceled"} {
102			t.Run(state, func(t *testing.T) {
103				m := longRun(t, 80, 24, state)
104				plain := func() string { return ansi.Strip(m.Render()) }
105	
106				if p := plain(); !strings.Contains(p, first) || strings.Contains(p, last) {
107					t.Fatalf("initially the body should show the source and not the last hop:\n%s", p)
108				}
109				m = feed(t, m, testutil.Key("end"))
110				if p := plain(); !strings.Contains(p, last) || strings.Contains(p, first) {
111					t.Errorf("after end: want the last hop and not the source:\n%s", p)
112				}
113				m = feed(t, m, testutil.Key("home"))
114				if p := plain(); !strings.Contains(p, first) || strings.Contains(p, last) {
115					t.Errorf("after home: want the source back:\n%s", p)
116				}
117				before := m.pathModel.table.Cursor()
118				m = feed(t, m, testutil.Key("pgdown"))
119				if after := m.pathModel.table.Cursor(); after <= before+1 {
120					t.Errorf("pgdown moved the cursor from %d to %d, want more than one row", before, after)
121				}
122			})
123		}
