6		"slices"
7		"strings"
8		"testing"
9		"time"
10	
11		"github.com/anthnel/devdesk/internal/engine"
12	)
13	
14	// envFakeEngineLog names the file the fake engine binary appends its argv to.
15	const envFakeEngineLog = "DEVDESK_TEST_FAKE_ENGINE_LOG"
16	
17	// init turns this test binary into a recording fake engine when the
18	// environment asks for it: it appends its arguments, one line per call, and
19	// exits before the testing flags are parsed. No real docker is involved.
20	func init() {
21		logPath := os.Getenv(envFakeEngineLog)
22		if logPath == "" {
23			return
24		}
25		f, err := os.OpenFile(logPath, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o600)
26		if err != nil {
27			os.Exit(3)
28		}
29		_, _ = f.WriteString(strings.Join(os.Args[1:], "\x1f") + "\n")
30		_ = f.Close()
31		os.Exit(0)
32	}
33	
34	// recordedEngineCalls points the current engine at this test binary and
35	// returns a reader for the recorded argument lists.
36	func recordedEngineCalls(t *testing.T) func() [][]string {
37		t.Helper()
38		logPath := t.TempDir() + string(os.PathSeparator) + "engine.log"
39		t.Setenv(envFakeEngineLog, logPath)
40		self, err := os.Executable()
41		if err != nil {
42			t.Fatalf("os.Executable: %v", err)
43		}
44		prev := engine.Current()
45		shape := prev
46		shape.Name, shape.Binary = engine.Docker, self
47		engine.SetCurrent(shape)
48		t.Cleanup(func() { engine.SetCurrent(prev) })
49		return func() [][]string {
50			raw, err := os.ReadFile(logPath)
51			if err != nil {
52				return nil
53			}
54			var calls [][]string
55			for _, line := range strings.Split(strings.TrimSpace(string(raw)), "\n") {
56				if line != "" {
57					calls = append(calls, strings.Split(line, "\x1f"))
58				}
59			}
60			return calls
61		}
62	}
63	
64	// Criterion 7: the reads behind the source selector and the producer never
65	// start, create or enter a container. The arguments recorded on the real
66	// engine wiring are ps, info and container inspect, nothing else.
67	func TestPathEngineReadsStartNothing(t *testing.T) {
68		calls := recordedEngineCalls(t)
69		e := systemPathEngine()
70	
71		listPathSources(context.Background(), e)
72		runProducerFrom(t, context.Background(), 1, pathTarget{Host: "10.0.0.9"}, testCtrSource(), time.Second, pathEngineWithoutNetwork(e))
73	
74		got := calls()
75		forbidden := []string{"start", "run", "exec", "create", "restart", "unpause", "attach", "kill", "stop", "pause", "rm", "cp", "commit"}
76		seen := map[string]bool{}
77		for _, args := range got {
78			if len(args) == 0 {
79				t.Fatalf("empty engine call in %v", got)
80			}
81			switch args[0] {
82			case "ps", "info":
83				seen[args[0]] = true
84			case "container":
85				if len(args) < 2 || args[1] != "inspect" {
86					t.Fatalf("engine call %v: only `container inspect` is allowed", args)
87				}
88				seen["inspect"] = true
89			default:
90				t.Fatalf("engine call %v: only ps, info and container inspect are allowed", args)
91			}
92			for _, a := range args {
93				if slices.Contains(forbidden, a) {
94					t.Fatalf("engine call %v carries the forbidden verb %q", args, a)
95				}
96			}
97		}
98		for _, want := range []string{"ps", "info", "inspect"} {
99			if !seen[want] {
100				t.Fatalf("the reads never ran %q (calls: %v): the guard would pass on nothing", want, got)
101			}
102		}
103	}
104	
105	// pathEngineWithoutNetwork keeps the real container wiring and replaces the
106	// socket and resolver parts, which this guard must not touch.
107	func pathEngineWithoutNetwork(e pathEngine) pathEngine {
108		f := &fakeEngine{traceFn: oneHopTrace}
109		fe := f.engine()
110		fe.engineName, fe.engineOS, fe.running, fe.inspect = e.engineName, e.engineOS, e.running, e.inspect
111		return fe
112	}
