691					t.Errorf("state %v: ctrl+o description = %q, want %q", state, s.Description, "Trace from…")
692				}
693			}
694		}
695	
696		off := pmWith(t, &fakeEngine{})
697		off.engine.supported = func() error { return errors.New("not linux") }
698		if sc := off.shortcuts(); !testutil.HasShortcut(sc, "ctrl+o") || !testutil.ShortcutDisabled(sc, "ctrl+o") {
699			t.Error("ctrl+o must stay listed and greyed where the trace is unsupported")
700		}
701	
702		pm.state = pathEditing
703		pm = openedPicker(t, pm)
704		// Rule 138: the arrows are obvious in a list, so only enter and esc are listed.
705		if got, want := testutil.ShortcutKeys(pm.shortcuts()), []string{"enter", "esc"}; !slices.Equal(got, want) {
706			t.Errorf("selector shortcuts = %v, want %v", got, want)
707		}
708	}
709	
710	// Rule 114: the help names the key.
711	func TestPathSourceKeyIsInTheHelp(t *testing.T) {
712		c := New(testConfig()).GetHelpContent()
713		found := false
714		for _, kb := range c.KeyBindings {
715			if strings.HasPrefix(kb.Key, "ctrl+o") {
716				found = true
717			}
718		}
719		if !found {
720			t.Error("no KeyBinding starts with ctrl+o")
721		}
722		for _, s := range c.Sections {
723			if strings.HasPrefix(s.Title, "Path Tab") && strings.Contains(s.Body, "ctrl+o") {
724				return
725			}
726		}
727		t.Error("the Path Tab help section does not mention ctrl+o")
728	}
