18	// pathColumns describes the Path column. Plain text in Cell, colour in Style
19	// (Rule 122). A silent hop is dim, never red: it is not a failure.
20	func pathColumns() []datatable.Column[pathStep] {
21		hop := datatable.Column[pathStep]{
22			Title: "Hop", Sizing: datatable.SizingFixed, MinWidth: 3,
23			Cell: pathStep.hopCell,
24		}
25		step := datatable.Column[pathStep]{
26			Title: "Step", Sizing: datatable.SizingFixed, MinWidth: 11,
27			Cell:  pathStep.stepCell,
28			Style: pathStepStyle,
29		}
30		address := datatable.Column[pathStep]{
31			Title: "Address", Sizing: datatable.SizingContent, MinWidth: 15, Flex: 1,
32			Cell:  pathStep.addressCell,
33			Style: pathAddressStyle,
34		}
35		rtt := datatable.Column[pathStep]{
36			Title: "RTT", Sizing: datatable.SizingFixed, MinWidth: 9,
37			Cell:  pathStep.rttCell,
38			Style: pathRTTStyle,
39		}
40		return []datatable.Column[pathStep]{hop, step, address, rtt}
41	}
