83	// view renders the table; the body is never replaced (Rule 139). The open
84	// selector is drawn over it.
85	func (pm *PathModel) view() string {
86		if pm.pickerOpen() {
87			return pm.viewWithPicker(pm.table.View())
88		}
89		return pm.table.View()
90	}
