			t.Fatalf("state %s: the selector did not open", state)
		}
		return m
	}
	return m
}

// Every body line is exactly width-2 cells, no escape sequence is cut, with and
// without the selector. The selector cannot open while a trace runs (refused,
// see TestPathSourceKeyIsRefusedWithAReason), so running is covered without it.
func TestPathContainerRowsFitTheTerminalWidth(t *testing.T) {
	for _, lc := range layoutCases() {
		for _, width := range []int{80, 60} {
			for _, state := range []string{"running", "done", "canceled"} {
				for _, picker := range []bool{false, true} {
					if picker && state == "running" {
						continue
					}
					name := fmt.Sprintf("%s/%d/%s/picker=%v", lc.name, width, state, picker)
					t.Run(name, func(t *testing.T) {
						m := containerRun(t, width, 24, state, lc, picker)
						body := m.Render()
						for i, line := range strings.Split(body, "\n") {
							if w := ansi.StringWidth(line); w != width-2 {
								t.Errorf("body line %d is %d cells wide, want %d: %q", i, w, width-2, ansi.Strip(line))
							}
						}
						if got := m.pathModel.table.RenderedWidth(); got != width-2 {
							t.Errorf("RenderedWidth = %d, want %d (Rule 116)", got, width-2)
						}
						plain := ansi.Strip(body)
						if strings.ContainsRune(plain, '\x1b') || strings.Contains(plain, "38;2;") {
							t.Errorf("an escape sequence survives the strip (cut sequence):\n%q", plain)
						}
						if picker {
							return // the selector covers the first rows by design
						}
						if !strings.Contains(plain, "container") || !strings.Contains(plain, "network") {
							t.Errorf("the container and network rows are missing:\n%s", plain)
						}
						if !strings.Contains(plain, "…") {
							t.Errorf("no truncation mark although names exceed the column:\n%s", plain)
						}
					})
				}
			}
		}
	}
}

// The trace row, in full at 80 columns, truncated at 60 (the Address column is
// 27 cells there).
func TestPathTraceRowAtTheTwoWidths(t *testing.T) {
	lc := layoutCases()[0]
	for _, state := range []string{"running", "done", "canceled"} {
		t.Run(state, func(t *testing.T) {
			at80 := ansi.Strip(containerRun(t, 80, 24, state, lc, false).Render())
			if !strings.Contains(at80, textTraceFromHost) {
				t.Errorf("80 columns: %q is not whole:\n%s", textTraceFromHost, at80)
			}
			at60 := ansi.Strip(containerRun(t, 60, 24, state, lc, false).Render())
			if strings.Contains(at60, textTraceFromHost) || !strings.Contains(at60, "from this machine") {
				t.Errorf("60 columns: want the trace text cut with a mark:\n%s", at60)
			}
		})
	}
}

// The Address column is 47 cells at 80 columns: a 47-cell name is whole, a
// 48-cell one is cut. Wide runes count two cells.
func TestPathAddressColumnIs47CellsAt80(t *testing.T) {
	cases := []struct {
		name  string
		cells string
		whole bool
	}{
		{"ascii 47", strings.Repeat("a", addressCellsAt80), true},
		{"ascii 48", strings.Repeat("a", addressCellsAt80+1), false},
		{"cjk 46", strings.Repeat("日", 23), true},
		{"cjk 48", strings.Repeat("日", 24), false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			// An inspection that failed leaves the bare name in the container row.
			m := onPathTab(t)
			m = feed(t, m, tea.WindowSizeMsg{Width: 80, Height: 24})
			captureLog(t)
			src := pathSource{ID: idWeb, Name: tc.cells}
			m.pathModel.source = src
			m = feed(t, m, testutil.Type("example.org")...)
			m = feed(t, m, testutil.Key("enter"))
			m = feed(t, m, pathResolvedMsg{gen: m.pathModel.gen, addr: netip.MustParseAddr("1.1.1.1"), route: defaultRouteHop(), source: src, ctrErr: errors.New("x")})

			plain := ansi.Strip(m.Render())
			if got := strings.Contains(plain, tc.cells); got != tc.whole {
				t.Errorf("%q whole = %v, want %v:\n%s", tc.cells, got, tc.whole, plain)
			}
			if !tc.whole && !strings.Contains(plain, "…") {
				t.Errorf("a cut name carries no mark:\n%s", plain)
			}
		})
	}
}

// 36 rows in a short body: end shows the last hop, home the container row again.
func TestPathContainerColumnScrolls(t *testing.T) {
	const last = "198.51.100.30"
	for _, state := range []string{"running", "done", "canceled"} {
		t.Run(state, func(t *testing.T) {
			m := containerRun(t, 80, 24, state, layoutCases()[2], false)
			if rows := len(m.pathModel.table.Items()); rows != 6+manyHops {
				t.Fatalf("rows = %d, want %d (container, network, source, interface, gateway, trace, 30 hops)", rows, 6+manyHops)
			}
			if p := ansi.Strip(m.Render()); !strings.Contains(p, "container") || strings.Contains(p, last) {
				t.Fatalf("initially: want the container row and not the last hop:\n%s", p)
			}
			m = feed(t, m, testutil.Key("end"))
			if p := ansi.Strip(m.Render()); !strings.Contains(p, last) || strings.Contains(p, textTraceFromHost) {
				t.Errorf("after end: want the last hop and not the trace row:\n%s", p)
			}
			m = feed(t, m, testutil.Key("home"))
			if p := ansi.Strip(m.Render()); !strings.Contains(p, "container") || strings.Contains(p, last) {
				t.Errorf("after home: want the container row back:\n%s", p)
			}
		})
	}
}

package netdiag

import (
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"slices"
	"strconv"
	"strings"
	"testing"
)

// DEVDESK-330 criterion 7, view level: the Path tab reaches the container
// engine only through a fixed list of read functions, and no source file of the
// package names a verb that starts, creates or enters a container. The runtime
// half is TestPathEngineReadsStartNothing.

const (
	dockerImportPath = "github.com/anthnel/devdesk/internal/docker"
	engineImportPath = "github.com/anthnel/devdesk/internal/engine"
)

// allowedDockerUses is every docker.<X> the Path tab may name: the read
// functions and the types they return.
var allowedDockerUses = []string{
	"Container", "ContainerNetworking", "EndpointNetwork",
	"ListContainersContext", "EngineOperatingSystem", "InspectContainerNetworking",
	"IsContainerID",
}

// allowedEngineUses is every engine.<X> the Path tab may name.
var allowedEngineUses = []string{"Current"}

// forbiddenVerbs are engine arguments that change a container or open a shell
// in it. A string literal equal to one of them has no business in this package.
var forbiddenVerbs = []string{
	"start", "exec", "run", "cp", "attach", "create", "restart", "unpause",
	"kill", "stop", "pause", "rm", "commit",
}

// engineViolations parses one Go source and returns one line per forbidden use:
// a selector on the docker or engine package outside its list, a string
// literal that is a forbidden verb, or an import of os/exec.
func engineViolations(filename string, src any) ([]string, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filename, src, 0)
	if err != nil {
		return nil, err
	}
	allowed := map[string][]string{} // local package name -> allowed selectors
	var out []string
	report := func(pos token.Pos, what string) {
		out = append(out, filepath.Base(filename)+":"+strconv.Itoa(fset.Position(pos).Line)+": "+what)
	}
	for _, imp := range f.Imports {
		path, _ := strconv.Unquote(imp.Path.Value)
		local := filepath.Base(path)
		if imp.Name != nil {
			local = imp.Name.Name
		}
		switch path {
		case dockerImportPath:
			allowed[local] = allowedDockerUses
		case engineImportPath:
			allowed[local] = allowedEngineUses
		case "os/exec":
			report(imp.Pos(), "imports os/exec")
		}
	}
	ast.Inspect(f, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.SelectorExpr:
			id, ok := x.X.(*ast.Ident)
			if !ok {
				return true
			}
			if list, isPkg := allowed[id.Name]; isPkg && !slices.Contains(list, x.Sel.Name) {
				report(x.Pos(), id.Name+"."+x.Sel.Name+" is not on the read-only list")
			}
		case *ast.BasicLit:
			if x.Kind != token.STRING {
				return true
			}
			if s, err := strconv.Unquote(x.Value); err == nil && slices.Contains(forbiddenVerbs, strings.TrimSpace(s)) {
				report(x.Pos(), "string literal "+x.Value+" is an engine verb that changes a container")
			}
		}
		return true
	})
	return out, nil
}

func TestPathTabCallsOnlyReadOnlyEngineFunctions(t *testing.T) {
	files, err := filepath.Glob("*.go")
	if err != nil || len(files) == 0 {
		t.Fatalf("no source file found (err %v)", err)
	}
	scanned := 0
	for _, file := range files {
		if strings.HasSuffix(file, "_test.go") {
			continue
		}
		raw, err := os.ReadFile(file)
		if err != nil {
			t.Fatal(err)
		}
		got, err := engineViolations(file, raw)
		if err != nil {
			t.Fatalf("%s: %v", file, err)
		}
		for _, v := range got {
			t.Errorf("%s", v)
		}
		scanned++
	}
	if scanned < 10 {
		t.Fatalf("scanned %d files: the guard would pass on nothing", scanned)
	}
}

// The detector itself: it fails on each kind of forbidden use, an alias does not
// hide one, and clean code passes.
func TestEngineViolationsDetectsForbiddenUses(t *testing.T) {
	const head = "package netdiag\nimport (\n\t\"github.com/anthnel/devdesk/internal/docker\"\n\teng \"github.com/anthnel/devdesk/internal/engine\"\n)\n"
	cases := []struct {
		name string
		body string
		want int
	}{
		{"clean", "var _ = docker.ListContainersContext\nvar _ docker.Container\nvar _ = docker.IsContainerID\nvar _ = eng.Current", 0},
		{"docker function outside the list", "var _ = docker.StartContainer", 1},
		{"docker exec", "var _ = docker.ExecInContainer", 1},
		{"engine function outside the list", "var _ = eng.Run", 1},
		{"verb as an argument", "var _ = []string{\"container\", \"start\", \"abc\"}", 1},
		{"exec verb", "var _ = []string{\"exec\", \"-it\"}", 1},
		{"run verb", "var _ = \"run\"", 1},
		{"cp verb", "var _ = \"cp\"", 1},
		{"attach verb", "var _ = \"attach\"", 1},
		{"read verbs are fine", "var _ = []string{\"ps\", \"info\", \"container\", \"inspect\"}", 0},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got, err := engineViolations("synthetic.go", head+tc.body+"\n")
			if err != nil {
				t.Fatal(err)
			}
			if len(got) != tc.want {
				t.Errorf("violations = %v, want %d", got, tc.want)
			}
		})
	}
	got, err := engineViolations("synthetic.go", "package netdiag\nimport \"os/exec\"\nvar _ = exec.Command\n")
	if err != nil || len(got) != 1 {
		t.Errorf("os/exec import: violations %v, err %v, want one", got, err)
	}
}

